    "#vs-skins{position:absolute;inset:0;z-index:40;background:rgba(6,8,14,.58);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);display:flex;align-items:center;justify-content:center;padding:18px;animation:vsSkinIn .26s ease;}",
