    "#vs-skins.out .vs-sk-sheet{animation:vsSkinSheetOut .2s ease forwards;}",
    "@keyframes vsSkinSheet{from{transform:translateY(48px) scale(.94);opacity:0}to{transform:none;opacity:1}}@keyframes vsSkinSheetOut{to{transform:translateY(24px) scale(.97);opacity:0}}",
    ".vs-sk-hd{display:flex;align-items:center;gap:12px;margin:0 2px 14px;}",
