    "@media (max-width:640px){.vs-sk-btn{min-width:0;max-width:58vw;}#vs-skins{padding:10px;}.vs-sk-grid{grid-template-columns:repeat(3,1fr);gap:8px;}.vs-sk-stage{width:72px;height:60px;}.vs-sk-tile{min-height:100px;padding:8px 4px 6px;}}",
    ".vs-hint{font:11px Arial;color:#6b7385;line-height:1.5;padding:8px 0 2px;}",
    ".vs-warn{display:flex;gap:10px;align-items:flex-start;margin:10px 0 6px;padding:10px 12px;border-radius:10px;border:1px solid rgba(255,190,80,.35);background:rgba(255,190,80,.08);font:11.5px Arial;color:#ffd699;line-height:1.5;}",
    ".vs-warn b{color:#ffcf70;}.vs-warn .i{flex:none;width:18px;height:18px;border-radius:50%;background:rgba(255,190,80,.25);color:#ffcf70;font:bold 12px/18px Arial;text-align:center;}",
    ".vs-locked{position:relative;}.vs-locked > *:not(.vs-lock){opacity:.35;pointer-events:none;filter:saturate(.6);}",
