    ".vs-ok{color:#9be7b5;}.vs-bad{color:#ff8a8a;}",
    "#vs-overlay,#vs-box,#vs-head,#vs-nav,#vs-body > *,.vs-sec > *,.vs-card > *,.vs-row > .l{transition:opacity .28s ease,background .28s ease,border-color .28s ease,box-shadow .28s ease,backdrop-filter .28s ease;}",
    "#vs-overlay.vs-peek{background:transparent;backdrop-filter:none;-webkit-backdrop-filter:none;}",
