    "#vs-overlay.vs-peek .vs-card,#vs-overlay.vs-peek .vs-live{border-color:transparent;background:transparent;}",
    "@media (max-width:640px){#vs-box{width:100vw;height:100vh;border-radius:0;}#vs-main{flex-direction:column;}#vs-nav{width:auto;display:flex;gap:4px;padding:8px;border-right:0;border-bottom:1px solid rgba(255,255,255,.06);overflow-x:auto;}.vs-ni{flex:none;padding:8px 12px;font-size:11.5px;}.vs-ni .b{display:none}#vs-body{padding:12px 14px 20px;}.vs-row input[type=range]{width:120px;}}",
    "#mybox,#nick_holder,#lastscore,#wy-hud,#time-hud,#timebot-hud,#clq,#mgraph-box,#bchat,#divtl,#divpl,#eemenu,#eb-hud,#ttbox,#mmap,#mtop-bar,#rk-box,#sv-box,#cpicker_panel,.popup-data,#settpage.opensett-data,#vs-box,#wn-box,#dx-box,#tc-pop,#tc-pop2{zoom:var(--wy-scale,1);}",
    "#vs-box,#wn-box,#dx-box,#tc-pop,#tc-pop2 .box,#rk-box,#sv-box{max-width:calc(100vw / var(--wy-scale,1))!important;max-height:calc(100vh / var(--wy-scale,1))!important;}",
    /* NTL's iframe popups (#rtlpage leaderboards / #utagpage tag uploader): .popup-data was a flat green box */
